mapper.select:
/*keyword > getPopularKeywordList*/ SELECT BT.ID, BT.CONTENTS_TYPE , BT.CONTENTS_ID, BT.TAGS, COUNT(1) AS CNT, BT.DELETE_YN, CT.ID AS CATEGORY_ID, CT.CATEGORY_NM, CT.CATEGORY_IMG_PATH FROM BOARD_TAGS BT INNER JOIN STORY ST ON ST.ID = BT.CONTENTS_ID INNER JOIN CATEGORY CT ON CT.ID = ST.CATEGORY_ID WHERE BT.DELETE_YN = 'N'
AND BT.TAGS LIKE CONCAT('%',#{keyword},'%')
GROUP BY BT.TAGS ORDER BY CNT DESC LIMIT ${listNo}
